function setLang(lang) {
  localStorage.setItem('mariage-lang', lang);
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.textContent.toLowerCase() === lang);
  });
  const t = page_i18n[lang];
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (t[key] !== undefined) el.textContent = t[key];
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    if (t[key] !== undefined) el.innerHTML = t[key];
  });
  document.querySelectorAll('[data-i18n-content]').forEach(el => {
    const key = el.getAttribute('data-i18n-content');
    if (t[key] !== undefined) el.setAttribute('content', t[key]);
  });
  document.documentElement.lang = lang === 'en' ? 'en' : 'ko';
}

document.addEventListener('DOMContentLoaded', () => {
  const saved = localStorage.getItem('mariage-lang');
  if (saved === 'en') setLang('en');
});

function toggleNav() {
  const links = document.querySelector('.nav-links');
  const btn   = document.querySelector('.nav-hamburger');
  if (!links) return;
  const open = links.classList.toggle('open');
  if (btn) btn.textContent = open ? '✕' : '☰';
}

// Close mobile nav when any link inside it is clicked
document.addEventListener('click', e => {
  if (e.target.closest('.nav-links a')) {
    const links = document.querySelector('.nav-links');
    const btn   = document.querySelector('.nav-hamburger');
    if (links) links.classList.remove('open');
    if (btn) btn.textContent = '☰';
  }
});
